      "translation": "vocês • lhe",
      "explanation": [
        "Ideia principal: ihr é uma palavra curta, mas com vários usos. 1) Pronome pessoal no nominativo: ihr = vocês (várias pessoas que se tratam por «tu»): Ihr seid nett. 2) Dativo de sie (ela): Ich helfe ihr — ajudo-a (a ela). 3) Possessivo: ihr Bruder — o irmão dela/deles.",
        "O possessivo ihr declina-se como ein: ihr Buch, ihre Mutter, ihren Vater, ihrem Kind. Pode significar «dela» (uma mulher) ou «deles/delas» (várias pessoas).",
        "Distingue: ihr (vocês, várias pessoas tratadas por «tu») ≠ Sie (tratamento de cortesia, sempre com maiúscula) ≠ Ihr/Ihnen (cortesia: seu/lhe)."
      ],
      "examples": [
        {
          "de": "Ihr seid heute spät.",
          "lv": "Hoje vocês estão atrasados."
        },
        {
          "de": "Kommt ihr morgen zur Party?",
          "lv": "Vocês vêm amanhã à festa?"
        },
        {
          "de": "Ich gebe ihr das Buch.",
          "lv": "Dou-lhe o livro."
        },
        {
          "de": "Ich helfe ihr beim Kochen.",
          "lv": "Ajudo-a a cozinhar."
        },
        {
          "de": "Ihr Bruder wohnt in Riga.",
          "lv": "O irmão dela mora em Riga."
        }
      ],
      "comparison": [
        {
          "word": "du",
          "meaning": "tu (uma pessoa)",
          "example": "Kommst du mit? – Vens também?"
        },
        {
          "word": "Sie",
          "meaning": "o senhor / a senhora (cortesia)",
          "example": "Wie heißen Sie? – Como se chama?"
        },
        {
          "word": "Ihnen",
          "meaning": "lhe (cortesia)",
          "example": "Ich helfe Ihnen gern. – Ajudo-o com todo o gosto."
        }
      ],
      "tip": [
        "Quando falas com duas ou mais pessoas que tratas por «tu», diz ihr + verbo com a terminação -t: ihr habt, ihr kommt.",
        "O ihr dativo reconhece-se pelo verbo: helfen, geben, danken, gehören pedem dativo."
      ],
      "important": [
        "Ihr (vocês, nominativo) escreve-se com minúscula no meio da frase; o Ihr/Ihnen de cortesia escreve-se sempre com maiúscula.",
        "Não uses ihr como «tu» — para uma pessoa é du, para várias é ihr."
      ],
