      "explanation": [
        "Ideia principal: das Mal é um substantivo neutro — “vez” (ocasião em que algo acontece): das erste Mal (a primeira vez), jedes Mal (cada vez), beim nächsten Mal (da próxima vez).",
        "Depois de um número, Mal fica normalmente no singular e escreve-se separado ou junto: zwei Mal / zweimal, drei Mal / dreimal. O plural die Male usa-se raramente, por exemplo mehrere Male.",
        "Mal é também uma partícula coloquial (com minúscula): Komm mal her! — Anda cá! É um uso diferente, que suaviza a ordem."
      ],
      "examples": [
        {
          "de": "Das erste Mal war schwer.",
          "lv": "A primeira vez foi difícil."
        },
        {
          "de": "Ich war schon zweimal in Berlin.",
          "lv": "Já estive duas vezes em Berlim."
        },
        {
          "de": "Jedes Mal vergesse ich es.",
          "lv": "Todas as vezes me esqueço disso."
        },
        {
          "de": "Beim nächsten Mal komme ich früher.",
          "lv": "Da próxima vez venho mais cedo."
        },
        {
          "de": "Noch einmal, bitte!",
          "lv": "Mais uma vez, por favor!"
        }
      ],
      "comparison": [
        {
          "word": "einmal",
          "meaning": "uma vez",
          "example": "Ich war einmal in Wien. – Já estive uma vez em Viena."
        },
        {
          "word": "mal",
          "meaning": "partícula (suaviza)",
          "example": "Komm mal her! – Anda cá!"
        },
        {
          "word": "die Zeit",
          "meaning": "tempo",
          "example": "Ich habe keine Zeit. – Não tenho tempo."
        }
      ],
      "tip": [
        "Combinações úteis: zum ersten Mal (pela primeira vez), diesmal (desta vez), jedes Mal (cada vez).",
        "O número de vezes exprime-se com -mal: einmal, zweimal, dreimal."
      ],
      "important": [
        "Das Mal significa também “sinal, mancha”: das Muttermal (sinal de nascença), das Denkmal (monumento).",
        "Depois de um número, a palavra composta escreve-se com minúscula: zweimal, e não “Zweimal”."
      ],
