        "Plural: die Männer (os homens, com trema). Genitivo: des Mannes, dativo plural: den Männern. Em palavras compostas: Ehemann, Geschäftsmann (plural Geschäftsleute).",
        "Diferença em relação a man: man (alguém, as pessoas em geral) é um pronome e escreve-se com minúscula e com um só n. O ser humano em geral chama-se der Mensch."
