      "translation": "tempo",
      "explanation": [
        "Ideia principal: das Wetter é um substantivo neutro que designa as condições meteorológicas — chuva, sol, vento, temperatura. O plural die Wetter praticamente não se usa; usa-se o singular: das Wetter ist schön.",
        "A pergunta é Wie ist das Wetter? Combinações frequentes: gutes/schlechtes Wetter (bom/mau tempo), der Wetterbericht (boletim meteorológico).",
        "Em português, tempo pode significar tanto as condições meteorológicas como o tempo enquanto conceito; em alemão são duas palavras diferentes: das Wetter e die Zeit."
      ],
      "examples": [
        {
          "de": "Das Wetter ist heute schön.",
          "lv": "Hoje está bom tempo."
        },
        {
          "de": "Wie ist das Wetter in Riga?",
          "lv": "Como está o tempo em Riga?"
        },
        {
          "de": "Wenn das Wetter schlecht ist, bleiben wir zu Hause.",
          "lv": "Quando está mau tempo, ficamos em casa."
        },
        {
          "de": "Morgen wird das Wetter besser.",
          "lv": "Amanhã o tempo vai melhorar."
        }
      ],
