        "Guten Appetit! é o voto que se faz antes de comer, em português \"bom apetite\". Quando se tem vontade de um prato concreto, diz-se Appetit auf + acusativo: Appetit auf Eis.",
        "Der Appetit é próximo de der Hunger, mas o apetite é a vontade de comer, enquanto a fome é uma necessidade física."
